#include <bits/stdc++.h>
using namespace std;

const int mod = 998244353;
bool check_valid(int v,int l,int r,int  pos,int n ,const vector<int>&list){
    for(int i: list){
        bool pre_ok =false;
        bool suff_ok =false;
        
        if(pos <=i){
            int cnt =min(i,l-1)+max(0,i-r);
            int req =(i+1)/2-1;
            
            if(cnt ==req){
                pre_ok=true;
            }
        }
        if(pos>=i){
            int cnt =max(0,l-i)+min(n-i+1,n-r);
            int req =(n-i+2)/2-1;
            
            if(cnt==req){
                suff_ok =true;
            }
        }
        if(!pre_ok&& !suff_ok){
            return false;
        }
    }
    return true;
    
}
int main() {
	// your code goes here
    ios::sync_with_stdio(0);
    cin.tie(0);
    int t;
    cin >> t;
    while(t--){
        int n;
        cin >> n;
        vector<int> a(n+1);
        vector<vector<int>> val(n+1);
        
        for(int i=1;i<=n;i++){
            cin >> a[i];
            
            val[a[i]].push_back(i);
        }
        
        vector<int> dp(2,0);
        dp[1] = 1;
        for(int v=1;v<n;v++){
            vector<int> next_dp(v+2,0);
            
            for(int l=1;l<=v;l++){
                if(dp[l] == 0){
                    continue;
                }
                
                int r = n-v+l;
                
                if(check_valid(v,l,r,l,n,val[v])){
                    next_dp[l+1]= (next_dp[l+1]+dp[l])%mod;
                }
                
                if(check_valid(v,l,r,r,n,val[v])){
                    next_dp[l] = (next_dp[l] + dp[l]) % mod;
                }
            }
            dp = move(next_dp);
        }
        
        int ans = 0;
        for(int l = 1;l<=n;l++){
            if(dp[l] == 0) continue;
            
            int r = l;
            if(check_valid(n,l,r,l,n,val[n])){
                ans = (ans + dp[l]) % mod;
            }
        }
        cout << ans << "\n";
    }
}
